pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 v) internal {
        vm.assume(true);
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue((!reverted && balBefore >= v && balAfter == balBefore - v) ||
            (reverted && balBefore < v && balAfter == balBefore));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
